pub fn get_problem(problem_id: Option<&str>) -> &'static Problem {
    problem_id
        .and_then(|id| PROBLEMS.iter().find(|problem| problem.id == id))
        .unwrap_or_else(|| {
            PROBLEMS
                .iter()
                .find(|problem| problem.id == DEFAULT_PROBLEM_ID)
                .expect("default problem exists")
        })
}
